/** Metro needs literal require paths; fail before writing if any combination is incomplete. */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const drinks = { heineken: 'nubo', corona: 'duna', stella: 'orbe', miller: 'milo', margarita: 'margarita', daiquiri: 'daiquiri' };
const actors = ['rafael', 'yuni', 'yoi', 'diego', 'lucia'];
const lines = [
  '// Generated by scripts/generate-drink-frames.mjs after checking every asset.',
  "import type { ImageSourcePropType } from 'react-native';",
  "import type { DrinkId } from './drinks';",
  "import type { AnimatedOpponentId } from './opponentDrink';",
  'type Poses = readonly [ImageSourcePropType, ImageSourcePropType, ImageSourcePropType, ImageSourcePropType, ImageSourcePropType, ImageSourcePropType, ImageSourcePropType, ImageSourcePropType, ImageSourcePropType];',
  'export const DRINK_FRAMES: Record<AnimatedOpponentId, Record<DrinkId, Poses>> = {',
];
for (const actor of actors) {
  lines.push(`  ${actor}: {`);
  for (const [id, slug] of Object.entries(drinks)) {
    lines.push(`    ${id}: [`);
    for (let i = 1; i <= 9; i++) {
      const asset = `assets/opponent-drinks-v2/${actor}/${slug}/pose-${String(i).padStart(2, '0')}.png`;
      if (!fs.existsSync(path.join(root, asset))) throw new Error(`Missing ${asset}`);
      lines.push(`      require('../../${asset}'),`);
    }
    lines.push('    ],');
  }
  lines.push('  },');
}
lines.push('};', '');
fs.writeFileSync(path.join(root, 'src/computer/drinkFrames.ts'), lines.join('\n'));
console.log('Registered 30 beverage/identity combinations, 270 PNG poses.');
